style.css:
@-moz-document domain("roblox.com") {
/* Main Background Changer */
    body, 
    .container-main, 
    .content, 
    #container-main, 
    .gandalf-roblox-pc-picker {
        background-image: url("https://i.pinimg.com/736x/a0/7f/ea/a07feafbd2f299eb82e6a0bd4e631d24.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* Makes the default dark/light panels transparent so your background shows through */
    .section-content, 
    .rbx-tab-content, 
    .tab-content, 
    .form-panel, 
    .menu-vertical,
    .left-col-container {
        background: rgba(25, 25, 25, 0.6) !important; /* Adjust 0.6 to change transparency */
    }
}
